<?php require 'bootstrap.php';$id=(int)($_GET['id']??0);$p=$id?q('SELECT * FROM products WHERE id=?',[$id])->fetch():['name'=>'','sku'=>'','description'=>'','price'=>'','stock'=>'','category_id'=>1,'featured'=>0,'active'=>1];if(!$p){http_response_code(404);exit('ไม่พบสินค้า');}$error='';
if($_SERVER['REQUEST_METHOD']==='POST' && post('action')==='replace_image') {
    verify_csrf();
    try {
        if(!$id)throw new RuntimeException('บันทึกสินค้าก่อนเปลี่ยนรูป');
        $image=upload_image();
        if(!$image)throw new RuntimeException('กรุณาเลือกไฟล์รูปภาพ');
        q('UPDATE products SET image=? WHERE id=?',[$image,$id]);
        flash('เปลี่ยนรูปสินค้าแล้ว โดยคงชื่อ ราคา และสต็อกเดิม');
        go('admin/product_edit.php?id='.$id);
    } catch(RuntimeException $ex) {
        $error=$ex instanceof PDOException?'ไม่สามารถบันทึกรูปภาพได้':$ex->getMessage();
    }
}
if($_SERVER['REQUEST_METHOD']==='POST' && post('action')!=='replace_image'){verify_csrf();try{$price=post('price');$stock=filter_var(post('stock'),FILTER_VALIDATE_INT);if(post('name')===''||mb_strlen(post('name'))>190||post('sku')===''||strlen(post('sku'))>40||post('description')===''||!preg_match('/^\d{1,10}(\.\d{1,2})?$/',$price)||$stock===false||$stock<0||$stock>2147483647)throw new RuntimeException('ตรวจสอบชื่อ รหัส ราคา และสต็อก');$cat=q('SELECT id FROM categories WHERE id=? AND active=1',[(int)post('category_id')])->fetchColumn();if(!$cat)throw new RuntimeException('กรุณาเลือกหมวดหมู่ที่เปิดใช้งาน');$image=upload_image()??($p['image']??'assets/images/category-'.$cat.'.svg');if($id&&!empty($p['variants_enabled'])&&$stock!==(int)$p['stock'])throw new RuntimeException('สินค้านี้ต้องปรับจำนวนผ่านเมนูสต๊อกแยกสี/ไซซ์');db()->beginTransaction();if($id){$fresh=q('SELECT * FROM products WHERE id=? FOR UPDATE',[$id])->fetch();if(isset($_POST['original_stock'])&&(int)post('original_stock')!==(int)$fresh['stock'])throw new RuntimeException('สต๊อกเปลี่ยนระหว่างแก้ไข กรุณาเปิดหน้าใหม่เพื่อใช้จำนวนล่าสุด');if($fresh['variants_enabled']&&$stock!==(int)$fresh['stock'])throw new RuntimeException('กรุณาปรับสต๊อกแยกสี/ไซซ์');$oldStock=(int)$fresh['stock'];}else $oldStock=0;$values=[$cat,post('sku'),post('name'),post('description'),$price,$stock,$image,isset($_POST['featured'])?1:0,isset($_POST['active'])?1:0];if($id){$values[]=$id;q('UPDATE products SET category_id=?,sku=?,name=?,description=?,price=?,stock=?,image=?,featured=?,active=? WHERE id=?',$values);}else q('INSERT INTO products(category_id,sku,name,description,price,stock,image,featured,active) VALUES (?,?,?,?,?,?,?,?,?)',$values);$savedProductId=$id?:((int)db()->lastInsertId());if($stock!==$oldStock)inventory_record($savedProductId,null,$stock-$oldStock,'adjust',null,(int)$admin['id'],'แก้ไขผ่านฟอร์มสินค้า');db()->commit();flash('บันทึกสินค้าแล้ว');go('admin/products.php');}catch(RuntimeException $ex){if(db()->inTransaction())db()->rollBack();$error=$ex instanceof PDOException?'ไม่สามารถบันทึกได้ รหัสสินค้าอาจซ้ำ':$ex->getMessage();}$p=array_merge($p,$_POST);}
admin_header($id?'แก้ไขสินค้า':'เพิ่มสินค้า');?><p class="error"><?=e(t($error))?></p><form method="post" enctype="multipart/form-data" class="panel"><?=csrf()?><input type="hidden" name="original_stock" value="<?=e($p['stock'])?>"><?php field('name','ชื่อสินค้า','text',$p['name']);field('sku','รหัสสินค้า','text',$p['sku']);?><label><?=e(t('รายละเอียด'))?><textarea name="description" required><?=e(localized_description($p))?></textarea></label><label><?=e(t('ราคา'))?><input type="number" min="0" step="0.01" name="price" value="<?=e($p['price'])?>" required></label><label><?=e(t('คงเหลือ'))?><input type="number" min="0" name="stock" value="<?=e($p['stock'])?>" required></label><label><?=e(t('หมวดหมู่'))?><select name="category_id"><?php foreach(q('SELECT * FROM categories WHERE active=1') as $c):?><option value="<?=$c['id']?>" <?=$c['id']==$p['category_id']?'selected':''?>><?=e(localized_name($c))?></option><?php endforeach ?></select></label><label>รูปภาพ (JPEG PNG WebP ไม่เกิน 5 MB; แปลงเป็น WebP 1200 × 1200)<input name="image" type="file" accept="image/jpeg,image/png,image/webp"></label><label class="checkbox"><input type="checkbox" name="featured" <?=$p['featured']?'checked':''?>> <?=e(t('สินค้าแนะนำ'))?></label><label class="checkbox"><input type="checkbox" name="active" <?=$p['active']?'checked':''?>> เปิดใช้งาน</label><button>บันทึกสินค้า</button></form><?php if($id): ?><section class="panel image-admin-panel"><h2>รูปภาพสินค้าปัจจุบัน</h2><figure class="admin-product-photo"><?=product_image_html($p,'',false,'260px')?><figcaption><?=e(product_image_note($p))?></figcaption></figure><p>เปลี่ยนเฉพาะรูปภาพโดยไม่แก้ชื่อ ราคา หรือสต็อก ไฟล์จะถูกแปลงเป็น WebP จัตุรัส 1200 × 1200 พร้อมภาพขนาดย่อ</p><form method="post" enctype="multipart/form-data"><?=csrf()?><input type="hidden" name="action" value="replace_image"><label>เลือกรูปเฉพาะสินค้านี้ (JPEG PNG WebP ไม่เกิน 5 MB)<input type="file" name="image" accept="image/jpeg,image/png,image/webp" required data-image-upload></label><img class="upload-preview" alt="ตัวอย่างภาพที่เลือกก่อนอัปโหลด" hidden data-upload-preview><button>เปลี่ยนเฉพาะรูปภาพ</button></form></section><?php endif; ?><?php admin_footer();?>
